const requeueStaleAnalysisRuns = `-- name: RequeueStaleAnalysisRuns :execrows
UPDATE analysis_runs SET status = CASE WHEN attempts >= 3 THEN 'failed' ELSE 'queued' END,
  error = CASE WHEN attempts >= 3 THEN 'worker stopped while processing this run' ELSE error END,
  locked_by = '', locked_at = NULL
WHERE status = 'running' AND locked_at < now() - make_interval(secs => $1::int)
`

func (q *Queries) RequeueStaleAnalysisRuns(ctx context.Context, staleSeconds int32) (int64, error) {
	result, err := q.db.Exec(ctx, requeueStaleAnalysisRuns, staleSeconds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

